dimensions.query:
select "deliveries"."id", "deliveries"."workspace_id", "deliveries"."message_id", "deliveries"."agent_id", "deliveries"."mode", "deliveries"."reason", "deliveries"."priority", "deliveries"."deadline", "deliveries"."status", "deliveries"."seq", "deliveries"."location_type", "deliveries"."location_node_id", "deliveries"."route_node_id", "deliveries"."route_node_kind", "deliveries"."route_node_role", "deliveries"."delivery_adapter", "deliveries"."dispatch_attempts", "deliveries"."next_attempt_at", "deliveries"."last_dispatch_error", "deliveries"."expires_at", "deliveries"."delivered_at", "deliveries"."acked_at", "deliveries"."dead_lettered_at", "deliveries"."retryable", "deliveries"."available_at", "deliveries"."error", "deliveries"."idempotency_key", "deliveries"."created_at", "deliveries"."updated_at", "agents"."name", "agents"."provider_name", "agents"."delivery_ack_seq", "messages"."body", "messages"."blocks", "messages"."metadata", "messages"."has_attachments", "messages"."thread_id", "messages"."created_at", "messages"."channel_id", "channels"."name", "dm_conversations"."id", "dm_conversations"."dm_type", "messages"."agent_id", (
        SELECT a.name FROM agents a WHERE a.id = "messages"."agent_id"
      ) from "deliveries" inner join "agents" on "deliveries"."agent_id" = "agents"."id" inner join "messages" on "deliveries"."message_id" = "messages"."id" inner join "channels" on "messages"."channel_id" = "channels"."id" left join "dm_conversations" on "dm_conversations"."channel_id" = "messages"."channel_id" where ("deliveries"."workspace_id" = ? and "agents"."location_type" = ? and "agents"."location_node_id" = ? and "deliveries"."status" in (?, ?) and "deliveries"."seq" > "agents"."delivery_ack_seq" and ("deliveries"."expires_at" IS NULL OR "deliveries"."expires_at" > ?) and "agents"."provider_name" = ?) order by "agents"."name" asc, "deliveries"."seq" asc
